update je_2025_tier2_admit_card
set password_for_examination=replace(to_char(dob,'DD-MM-YYYY'),'-','')
where dob is not null;

select distinct comp_time,examtime,count(*) from je_2025_tier2_admit_card group by comp_time,examtime;

update je_2025_tier2_admit_card set 
examtime='02:00 PM To 04:00 PM' where comp_time='No' and examtime is not null and reg_number<>'10000000001';

update je_2025_tier2_admit_card set 
examtime='02:00 PM To 04:40 PM' where comp_time='Yes' and examtime is not null and reg_number<>'10000000001';

select * into je_2025_tier2_admit_card_bkp_sallu from je_2025_tier2_admit_card;

select distinct repotime,count(*) from je_2025_tier2_admit_card group by repotime;

update je_2025_tier2_admit_card
set repotime='12:30 PM' where repotime='12.30 PM';---7327

select distinct gateclose,count(*) from je_2025_tier2_admit_card group by gateclose;

update je_2025_tier2_admit_card
set gateclose='01:30 PM' where gateclose in ('1.30 PM','1:30 PM');

update je_2025_tier2_admit_card a
set a.identification_mark=b.identification_mark
from je_2025_tier1_admit_card b
where a.reg_number=b.reg_number
and a.region in ('NER','MPR','CR','SR');---8842

select distinct shift,count(*) from je_2025_tier2_admit_card group by shift;

select distinct category,count(*) from je_2025_tier2_admit_card group by category;

update je_2025_tier2_admit_card set category='0' where category='EWS';---111
update je_2025_tier2_admit_card set category='9' where category='UR';---110
update je_2025_tier2_admit_card set category='1' where category='SC';---266
update je_2025_tier2_admit_card set category='2' where category='ST';---135
update je_2025_tier2_admit_card set category='6' where category='OBC';---260

select distinct gender,count(*) from je_2025_tier2_admit_card group by gender;

select distinct ph_code,count(*) from je_2025_tier2_admit_card group by ph_code;
select distinct ph,count(*) from je_2025_tier2_admit_card group by ph;

update je_2025_tier2_admit_card
set ph='Yes' where ph in ('1','YES');--62+32

update je_2025_tier2_admit_card
set ph='No' where ph in ('2','NO');--1619+3521

update je_2025_tier2_admit_card
set ph=null where ph='NULL';--265